 <div class="overlay" id="startOverlay"><section class="panel"><div class="eyebrow">FIELD BRIEFING &nbsp; / &nbsp; 09.17.26</div><h1>ONE ROUND<br><span>LEFT.</span></h1><p class="panel-copy">The breach is sealed. Your sidearm has exactly one round—and the dead don't stay down. Put it to work, then find where it landed. Clear the sector. Get out.</p><div class="rule"></div><div class="rules"><div class="rule-item"><b><span class="key">W A S D</span> MOVE</b>Arrow keys also work</div><div class="rule-item"><b><span class="key">MOUSE</span> AIM</b>Click to lock / look</div><div class="rule-item"><b><span class="key">CLICK</span> FIRE</b>One shot. One target.</div><div class="rule-item"><b><span class="key">E</span> RETRIEVE</b>Get close to your bullet</div></div><div class="start-row"><span class="start-note">THE ROUND IS NEVER LOST.<br>JUST SOMEWHERE ELSE.</span><button class="action-btn" id="startBtn">ENTER THE SECTOR &nbsp; ↗</button></div></section></div>
 <div class="overlay hidden" id="endOverlay"><section class="panel end"><div class="result-tag" id="resultTag">MISSION COMPLETE</div><h1 id="resultTitle">SECTOR<br><span>CLEARED.</span></h1><p class="panel-copy" id="resultCopy">You got out. The round made it home too.</p><div class="rule"></div><div class="start-row"><span class="start-note" id="resultStats">TIME 00:00<br>HOSTILES 05 / 05</span><button class="action-btn" id="restartBtn">RUN IT BACK &nbsp; ↗</button></div></section></div>
 </main>
 <script>
+(()=>{
+const canvas=document.getElementById('view'),ctx=canvas.getContext('2d',{alpha:false}),mapCanvas=document.getElementById('map'),mctx=mapCanvas.getContext('2d');
+const $=id=>document.getElementById(id), TAU=Math.PI*2, FOV=Math.PI/3;
+const W=21,H=17,grid=Array.from({length:H},(_,y)=>Array.from({length:W},(_,x)=>x===0||y===0||x===W-1||y===H-1?1:0));
+for(let y=1;y<H-1;y++){if(![3,8,13].includes(y))grid[y][7]=1;if(![5,10,14].includes(y))grid[y][14]=1;}
+[[3,6],[4,6],[3,7],[4,7],[10,4],[11,4],[10,5],[16,7],[17,7],[16,8],[4,10],[5,10],[10,11],[11,11],[17,12],[4,13],[5,13],[10,14],[11,14]].forEach(([x,y])=>grid[y][x]=1);
+const spawn=()=>[
+ {x:5.4,y:3.5,hp:1,alive:true,kind:0}, {x:10.4,y:2.5,hp:1,alive:true,kind:1},
+ {x:17.3,y:3.4,hp:1,alive:true,kind:2}, {x:9.6,y:9.8,hp:1,alive:true,kind:0},
+ {x:17.3,y:11.2,hp:1,alive:true,kind:1}
+];
+let player,enemies,bullet,playing=false,ended=false,health=100,ammo=true,startAt=0,elapsed=0,last=0,shotAt=0,damageAt=0,flashAt=0,keys={},mouseTurn=0,soundOn=false,audio=null,alertTimer=0,locked=false;
+const exit={x:18.35,y:14.45};
+function reset(){player={x:2.5,y:2.5,a:0.12};enemies=spawn();bullet=null;health=100;ammo=true;elapsed=0;ended=false;startAt=performance.now();last=startAt;playing=true;keys={};$('startOverlay').classList.add('hidden');$('endOverlay').classList.add('hidden');$('alert').classList.remove('show');$('objective').textContent='CLEAR THE SECTOR';$('objectiveSub').textContent='ELIMINATE ALL HOSTILES · RECOVER ROUND';updateHUD();}
+function start(){if(!playing)reset();if(soundOn)ensureAudio()}
+function setSize(){const w=innerWidth,h=innerHeight,scale=Math.min(1,960/w,600/h);canvas.width=Math.max(360,Math.round(w*scale));canvas.height=Math.max(240,Math.round(h*scale));mapCanvas.width=mapCanvas.clientWidth*devicePixelRatio;mapCanvas.height=mapCanvas.clientHeight*devicePixelRatio;mctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0)}
+addEventListener('resize',setSize);setSize();
+function wall(x,y){return x<0||y<0||x>=W||y>=H||grid[y][x]!==0}
+function blocked(x,y,r=.2){return wall(Math.floor(x-r),Math.floor(y-r))||wall(Math.floor(x+r),Math.floor(y-r))||wall(Math.floor(x-r),Math.floor(y+r))||wall(Math.floor(x+r),Math.floor(y+r))}
+function wrap(a){return (a+Math.PI*3)%TAU-Math.PI}
+function castDistance(ox,oy,dx,dy){let mx=Math.floor(ox),my=Math.floor(oy),ddx=Math.abs(1/dx),ddy=Math.abs(1/dy),sx=dx<0?-1:1,sy=dy<0?-1:1,sdx=(dx<0?ox-mx:mx+1-ox)*ddx,sdy=(dy<0?oy-my:my+1-oy)*ddy,side=0;for(let i=0;i<80;i++){if(sdx<sdy){sdx+=ddx;mx+=sx;side=0}else{sdy+=ddy;my+=sy;side=1}if(wall(mx,my))break}const d=side===0?(mx-ox+(1-sx)/2)/dx:(my-oy+(1-sy)/2)/dy;return {d:Math.max(.01,d),side,mx,my,hit:side===0?oy+d*dy:ox+d*dx}}
+const zBuffer=[];
+function render(){const cw=canvas.width,ch=canvas.height;if(!cw||!ch)return;const horizon=Math.floor(ch*.47),img=ctx;let sky=img.createLinearGradient(0,0,0,horizon);sky.addColorStop(0,'#1a201d');sky.addColorStop(1,'#59615a');img.fillStyle=sky;img.fillRect(0,0,cw,horizon);let floor=img.createLinearGradient(0,horizon,0,ch);floor.addColorStop(0,'#292d29');floor.addColorStop(1,'#101311');img.fillStyle=floor;img.fillRect(0,horizon,cw,ch-horizon);const focal=cw/(2*Math.tan(FOV/2));
+// Perspective floor seams
+img.lineWidth=1;for(let j=1;j<10;j++){let t=j/10,y=horizon+(ch-horizon)*t*t;img.strokeStyle=`rgba(181,196,166,${.015+t*.035})`;img.beginPath();img.moveTo(0,y);img.lineTo(cw,y);img.stroke()}for(let j=-10;j<=10;j++){img.strokeStyle='rgba(181,196,166,.025)';img.beginPath();img.moveTo(cw/2+j*2,horizon);img.lineTo(cw/2+j*cw*.11,ch);img.stroke()}
+const rayCount=cw;zBuffer.length=rayCount;
+for(let x=0;x<rayCount;x++){const cameraX=2*x/cw-1,angle=player.a+Math.atan(cameraX*Math.tan(FOV/2)),dx=Math.cos(angle),dy=Math.sin(angle),hit=castDistance(player.x,player.y,dx,dy),dist=hit.d*Math.cos(angle-player.a);zBuffer[x]=dist;let wallX=hit.side===0?player.y+hit.d*dy:player.x+hit.d*dx;wallX-=Math.floor(wallX);let stripe=(Math.floor(wallX*8)%2),height=Math.min(ch*2,focal*.82/dist),top=horizon-height/2,shade=Math.max(.16,1-dist/12)*(hit.side===1?.74:1),base=stripe?91:78,green=Math.floor((base+((hit.my*9+hit.mx*5)%14))*shade);img.fillStyle=`rgb(${Math.floor(green*.85)},${green},${Math.floor(green*.83)})`;img.fillRect(x,top,1,height);if(Math.floor(wallX*8)===0){img.fillStyle=`rgba(215,255,84,${.09*shade})`;img.fillRect(x,top,1,height)}let band=Math.max(1,Math.floor(height/12));img.fillStyle=`rgba(0,0,0,${.12*shade})`;for(let by=top+band;by<top+height;by+=band)img.fillRect(x,by,1,1);img.fillStyle=`rgba(0,0,0,${Math.min(.78,dist*.065)})`;img.fillRect(x,top,1,height)}
+// Exit marker glows through the sector
+const exitRelX=exit.x-player.x,exitRelY=exit.y-player.y,exitDepth=exitRelX*Math.cos(player.a)+exitRelY*Math.sin(player.a),exitSide=-exitRelX*Math.sin(player.a)+exitRelY*Math.cos(player.a);if(exitDepth>.2){let ex=cw/2+exitSide/exitDepth*focal,ey=horizon+focal*.48/exitDepth,sz=focal*.55/exitDepth;if(ex>-sz&&ex<cw+sz&&zBuffer[Math.max(0,Math.min(rayCount-1,Math.floor(ex)))]>exitDepth){img.save();img.globalAlpha=Math.max(.18,Math.min(.8,1-exitDepth/13));img.fillStyle='#d7ff54';img.shadowColor='#d7ff54';img.shadowBlur=18;img.fillRect(ex-sz*.45,ey-sz*.65,sz*.9,sz*.12);img.fillRect(ex-sz*.45,ey-sz*.65,sz*.1,sz*.8);img.fillRect(ex+sz*.35,ey-sz*.65,sz*.1,sz*.8);img.fillRect(ex-sz*.45,ey+sz*.05,sz*.9,sz*.12);img.restore()}}
+// Billboard creatures and recoverable round
+let sprites=enemies.filter(e=>e.alive).map(e=>({...e,type:'enemy'}));if(bullet)sprites.push({...bullet,type:'bullet'});sprites.sort((a,b)=>Math.hypot(b.x-player.x,b.y-player.y)-Math.hypot(a.x-player.x,a.y-player.y));
+for(const s of sprites){let rx=s.x-player.x,ry=s.y-player.y,depth=rx*Math.cos(player.a)+ry*Math.sin(player.a),side=-rx*Math.sin(player.a)+ry*Math.cos(player.a);if(depth<=.12)continue;let sx=cw/2+side/depth*focal,cell=Math.max(0,Math.min(rayCount-1,Math.floor(sx)));if(depth>zBuffer[cell]+.35)continue;
+if(s.type==='bullet'){let size=Math.max(3,focal*.15/depth),fy=horizon+focal*.48/depth;img.save();img.globalAlpha=Math.max(.35,1-depth/14);img.shadowColor='#d7ff54';img.shadowBlur=size*2;img.fillStyle='#d7ff54';img.beginPath();img.ellipse(sx,fy,size*1.45,size*.7,-.25,0,TAU);img.fill();img.fillStyle='#fff4a8';img.beginPath();img.ellipse(sx,fy-size*.15,size*.85,size*.34,-.25,0,TAU);img.fill();img.restore();continue}
+const size=Math.min(ch*1.2,focal*1.35/depth),baseY=horizon+size*.43,bodyW=size*.62,topY=baseY-size;drawEnemy(img,sx,topY,bodyW,size,s.kind,depth);
+}
+// weapon breath sway
+if(playing){let sway=Math.sin(performance.now()*.003)*1.7;document.getElementById('weapon').style.marginLeft=`${sway}px`}
+}

