function updateHUD(){let left=enemies.filter(e=>e.alive).length;$('healthNum').textContent=health;$('threat').textContent=String(left).padStart(2,'0');$('ammoNum').textContent=ammo?'1':'0';$('ammoIcon').classList.toggle('empty',!ammo);$('ammoState').textContent=ammo?'IN CHAMBER':bullet?'DOWNRANGE':'RECOVERED';$('healthBars').innerHTML=Array.from({length:5},(_,i)=>`<b class="${health<=i*20?'off':''}"></b>`).join('');if(left===0){$('objective').textContent=ammo?'REACH EXTRACTION':'RECOVER THE ROUND';$('objectiveSub').textContent=ammo?'EXIT MARKED · FOLLOW THE GREEN BEACON':'YOUR ROUND IS STILL OUT THERE';}}
function showAlert(message){const node=$('alert');node.textContent=message;node.classList.add('show');clearTimeout(alertTimer);alertTimer=setTimeout(()=>node.classList.remove('show'),1350)}
